(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*12, w2 = Math.cos(y*0.022-t*0.3)*10;
  const w3 = Math.sin((x+y)*0.012+t*0.4)*8, w4 = Math.cos((x-y)*0.015-t*0.35)*9;
  const sx = x+w1+w3, sy = y+w2+w4;
  const src = [
    [140+Math.sin(t*0.5)*120, 70+Math.cos(t*0.35)*50, 0.09, 2.1, 1.0],
    [340+Math.cos(t*0.45)*110, 90+Math.sin(t*0.6)*60, 0.07, 1.8, 0.9],
    [240+Math.sin(t*0.3+2)*160, 120+Math.cos(t*0.5+1)*100, 0.055, 2.5, 1.1],
    [100+Math.cos(t*0.7+1)*90, 190+Math.sin(t*0.55+3)*70, 0.11, 1.6, 0.85],
    [380+Math.sin(t*0.38+4)*100, 50+Math.cos(t*0.8+2)*80, 0.065, 2.8, 1.05],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.5)*90, 0.08, 2.0, 0.95],
    [300+Math.sin(t*0.55+3)*80, 180+Math.cos(t*0.42+1)*65, 0.1, 1.9, 0.9],
    [60+Math.cos(t*0.48+2)*70, 130+Math.sin(t*0.65+4)*55, 0.075, 2.3, 1.0]
  ];
  let aS=0, iS=0, aS2=0, iS2=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const att = 1/(1+d*0.003);
    aS += Math.sin(d*f-t*sp)*w*att;
    iS += Math.sin(d*f*0.7+t*sp*0.6+1.5)*w*att;
    aS2 += Math.sin(d*f*1.6-t*sp*1.3+0.8)*w*att*0.6;
    iS2 += Math.sin(d*f*1.2+t*sp*0.9+3.2)*w*att*0.6;
  }
  const act=(aS+aS2)/12.8, inh=(iS+iS2)/12.8;
  const bg = (Math.sin(sx*0.035+sy*0.028+t*0.7)+Math.sin(sx*0.028-sy*0.038+t*1.0)+Math.sin(sx*0.05+sy*0.01-t*0.5))/3;
  const fine = (Math.sin(sx*0.12+sy*0.09+t*1.5)*Math.sin(sx*0.08-sy*0.11+t*1.2)+Math.sin((sx+sy)*0.15-t*2.5)*0.5)/1.5;
