  const ring = Math.sin(dist*0.08-t*2.5)*Math.exp(-dist*0.005)*0.4;
  const laplacian = (Math.sin(sx*0.08+t)*Math.sin(sy*0.08-t*0.7)+Math.sin((sx+sy)*0.06-t*1.5)+Math.sin((sx-sy)*0.07+t*1.8))/3;
  const reaction = Math.tanh((act - inh*0.65 + bg*0.35 + spiral*0.4 + ring + fine*0.15 + laplacian*0.2)*2.0);
  const cell = Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin(sx*0.17+t*0.8)*Math.sin(sy*0.11-t*0.6))*1.8)*0.2;
  const micro = Math.sin(sx*0.3+t*3)*Math.sin(sy*0.3-t*2.5)*0.08*Math.abs(reaction);
  const blend = reaction*0.65+cell*0.2+micro, v = blend*0.5+0.5;
